#include <iterator>
#include <map>
#include <memory>
#include <stdexcept>
#include <vector>

namespace Slic3r::GUI::JusPrin {

namespace {

void load_icon(GLTexture& texture, const std::string& name, int size_px)
{
    const boost::filesystem::path path = boost::filesystem::path(resources_dir()) / "jusprin" / "ui" / "icons" / (name + ".svg");
    boost::nowide::ifstream file(path.string());
    if (!file.is_open())
        throw std::runtime_error("canvas icon is missing: " + path.string());
    std::string svg((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
    // The icons are drawn in currentColor for the web pages; nanosvg reads that as grey.
    boost::replace_all(svg, "currentColor", "#FFFFFF");

    std::unique_ptr<NSVGimage, decltype(&nsvgDelete)> image(nsvgParse(svg.data(), "px", 96.0f), nsvgDelete);
    if (image == nullptr || image->width <= 0.f)
        throw std::runtime_error("canvas icon could not be parsed: " + path.string());
    std::unique_ptr<NSVGrasterizer, decltype(&nsvgDeleteRasterizer)> rasterizer(nsvgCreateRasterizer(), nsvgDeleteRasterizer);
    std::vector<unsigned char> pixels(size_t(size_px) * size_px * 4, 0);
    nsvgRasterize(rasterizer.get(), image.get(), 0, 0, float(size_px) / image->width, pixels.data(), size_px, size_px, size_px * 4);

    texture.reset();
    if (!texture.load_from_raw_data(std::move(pixels), size_px, size_px))
        throw std::runtime_error("canvas icon could not be uploaded: " + path.string());
}

} // namespace

float canvas_ui_scale(const GLCanvas3D& canvas) { return float(canvas.get_wxglcanvas()->GetDPIScaleFactor()); }

unsigned int canvas_icon_texture(const std::string& name, int size_px)
{
    // Keyed by size as well as name: a display-scale change asks for a
    // different size and gets its own texture rather than a scaled one.
    static std::map<std::pair<std::string, int>, GLTexture> cache;
    GLTexture& texture = cache[{name, size_px}];
    if (texture.get_id() == 0)
        load_icon(texture, name, size_px);
    return texture.get_id();
#pragma once

#include <wx/bitmap.h>
#include <wx/gdicmn.h>
#include <wx/event.h>
#include <wx/splash.h>

class wxPaintEvent;

namespace Slic3r::GUI::JusPrin {

class ShellTheme;

// JusPrin's startup splash while the JusPrin view is on: the stacked lockup,
// the version, and on the Mac a bar whose segment sweeps back and forth while
// the app loads. It has no steps or percentage: the main thread is blocked
// through most of startup, so only motion that runs off it (Core Animation)
// can show; Windows and Linux draw no bar. Drawn on the "JusPrin v2" canvas,
// page "Splash & About", boards splash-about-01 to 03. Stays open until it is
// destroyed (close_splash_when_shown).
class SplashWindow : public wxSplashScreen
{
public:
    // pos is where the main window last stood; the splash centres on that
    // display.
    SplashWindow(const ShellTheme& theme, const wxPoint& pos);

    // Shows and paints the splash, and on the Mac starts the bar, before
    // startup blocks the main thread.
    void present();

    // Closes the splash when window is first shown.
    void close_when_shown(wxWindow& window);

    // wxSplashScreen sees every event in the app first, and closes itself on
    // any key or click; startup holds the splash across the whole load, so it
    // ignores them (as OrcaSlicer's splash does, for the same use-after-free).
    // It watches here for the main window's first show instead: a handler
    // bound on MainFrame would not hear it, because MainFrame's own wxEVT_SHOW
    // handler is bound after the shell attaches and does not pass it on.
    int FilterEvent(wxEvent& event) override;

private:
    void on_paint(wxPaintEvent& event);

    const ShellTheme& m_theme;
    wxBitmap          m_lockup;
    wxWindow*         m_close_with{nullptr};
};

} // namespace Slic3r::GUI::JusPrin
