// File › Import › Import from OrcaSlicer…'s window.
struct OrcaImportMetrics { int width{0}; int height{0}; };

// The startup splash: a square window, the version line's and the bar's top,
// the bar's track and moving segment, and how long one sweep across takes.
struct SplashMetrics
{
    int size{0};
    int version_top{0};
    int bar_top{0};
    int bar_width{0};
    int bar_segment_width{0};
    int bar_sweep_ms{0};
};

// Help › About JusPrin's window.
struct AboutMetrics { int width{0}; int lockup_height{0}; int help_label_width{0}; int copied_ms{0}; };
    const nlohmann::json& orca_import = component.at("orcaImport");
    m.orca_import.width  = parse_int(orca_import, "component.orcaImport", "width");
    m.orca_import.height = parse_int(orca_import, "component.orcaImport", "height");

    const nlohmann::json& splash = component.at("splash");
    m.splash.size              = parse_int(splash, "component.splash", "size");
    m.splash.version_top       = parse_int(splash, "component.splash", "versionTop");
    m.splash.bar_top           = parse_int(splash, "component.splash", "barTop");
    m.splash.bar_width         = parse_int(splash, "component.splash", "barWidth");
    m.splash.bar_segment_width = parse_int(splash, "component.splash", "barSegmentWidth");
    m.splash.bar_sweep_ms      = parse_int(splash, "component.splash", "barSweepMs");

    const nlohmann::json& about = component.at("about");
    CHECK(m.button.secondary_small.padding_x == 12);
    CHECK(m.button.secondary_small.text_role == TextRole::BodySmall);
    CHECK(m.button.link.height == 26);
    CHECK(m.button.link.padding_x == 4);
    CHECK(m.button.link.text_role == TextRole::LabelBold);
    CHECK(m.progress_height == 4);
    CHECK(m.splash.size == 480);
    CHECK(m.splash.version_top == 355);
    CHECK(m.splash.bar_top == 397);
    CHECK(m.splash.bar_width == 160);
    CHECK(m.splash.bar_segment_width == 48);
    CHECK(m.splash.bar_sweep_ms == 1200);
    CHECK(m.about.width == 400);
    CHECK(m.about.lockup_height == 43);
                             "component.orcaImport");
}

// The startup splash (canvas "JusPrin v2", page "Splash & About", boards
// splash-about-01 to 03, agreed 2026-11-08): a square window the size of the
// stacked lockup artwork, whose drawing ends at y 331; the version line and
// the bar under it. The bar's segment slides across its track and back, each
// way in barSweepMs; the bar is drawn only on macOS.
TEST_CASE("the startup splash keeps the canvas's sizes", "[brand]")
{
    const json tokens = load_tokens();
    const json& splash = tokens.at("component").at("splash");
    require_exact_table<int>(splash,
                             {{"size", 480}, {"versionTop", 355}, {"barTop", 397}, {"barWidth", 160},
                              {"barSegmentWidth", 48}, {"barSweepMs", 1200}},
                             "component.splash");
    REQUIRE(splash.at("barSegmentWidth").get<int>() < splash.at("barWidth").get<int>());
    REQUIRE(splash.at("barTop").get<int>() + tokens.at("component").at("progress").at("height").get<int>() <
            splash.at("size").get<int>());
}

